package dev.pedro.learning.ecommerce.payment.api;import dev.pedro.learning.ecommerce.payment.domain.PaymentRepository;import jakarta.ws.rs.*;import jakarta.ws.rs.core.MediaType;import java.util.UUID;@Path("/payments")@Produces(MediaType.APPLICATION_JSON)public class PaymentResource{private final PaymentRepository payments;public PaymentResource(PaymentRepository payments){this.payments=payments;}@GET @Path("/order/{orderId}")public PaymentResponse byOrder(@PathParam("orderId")UUID orderId){var p=payments.findByOrderId(orderId);if(p==null)throw new NotFoundException();return PaymentResponse.from(p);}}